  void RefreshVersionSelection(){if(versionSelection==null)return;var chosen=CheckedOptions();versionSelection.Text=string.Format(L.Get("VersionsSelected"),chosen.Count);if(versionGrid.Columns.Count==7){var visible=VisibleVersionOptions();int picked=visible.Count(o=>checkedVersions.Contains(OptionId(o)));versionGrid.Columns[0].HeaderText=picked==0?"☐":picked==visible.Count?"☑":"◩";}if(installVersions==null)return;bool one=chosen.GroupBy(o=>o.Package.Manifest.id).All(g=>g.Count()==1);installVersions.Enabled=!busy&&CatalogMatchesTarget()&&chosen.Count>0&&one;archiveVersions.Enabled=!busy&&chosen.Count>0;forgetVersions.Enabled=!busy&&chosen.Count>0;versionReason.Text=chosen.Count==0?L.Get("SelectVersionsHint"):!one?L.Get("OneVersionHint"):L.Get("VersionActionsHint");hints.SetToolTip(versionReason,L.Get("ArchiveHint"));}
  void UpdateGroupActions(){if(renderingVersions)return;RefreshVersionSelection();}
  void CompareCheckedVersions(){var chosen=CheckedOptions();if(chosen.Count!=2||chosen[0].Package.Manifest.id!=chosen[1].Package.Manifest.id){Dialogs.Show(L.Get("CompareHint"),Text);return;}var a=chosen[1].Package;var b=chosen[0].Package;var difference=VersionDifference.Compare(a,b);string summary=string.Format(L.Get("CompareSummary"),difference.Added.Count,difference.Removed.Count,difference.Changed.Count);string body="A: "+PackageVersions.Display(a)+Environment.NewLine+a.Folder+Environment.NewLine+"B: "+PackageVersions.Display(b)+Environment.NewLine+b.Folder+Environment.NewLine+Environment.NewLine+L.Get("CompareMetadataOnly")+Environment.NewLine+Environment.NewLine+string.Join(Environment.NewLine,difference.Added.Select(p=>"+ "+p).Concat(difference.Removed.Select(p=>"− "+p)).Concat(difference.Changed.Select(p=>"~ "+p)));using(var dialog=CreateResultDialog(summary,body,new List<string>(),null)){dialog.Text=L.Get("CompareVersions");dialog.ShowDialog(this);}}
  async Task UpdateCheckedToRecommended(){if(busy||!CatalogMatchesTarget())return;var selected=Selected();if(selected.Count==0)return;if(selected.Any(r=>LatestPackage(r)==null||r.Installed==null)){Dialogs.Show(L.Get("UpdateRecommendedHint"),Text);return;}foreach(var row in selected){int index=rows.IndexOf(row);grid.Rows[index].Cells[2].Value=LatestPackage(row).Folder;grid.Rows[index].Cells[0].Value=true;}await Install();}
  async Task InstallCheckedVersions(){if(busy)return;var options=CheckedOptions();if(options.Count==0)return;if(options.GroupBy(o=>o.Package.Manifest.id).Any(g=>g.Count()>1)){Dialogs.Show(L.Get("OneVersionHint"),Text);return;}search.Text="";filter.SelectedIndex=0;categoryFilter.SelectedIndex=0;ApplyFilter();CheckVisible(false);foreach(var option in options){int index=rows.FindIndex(r=>RowId(r)==option.Package.Manifest.id);if(index<0)continue;grid.Rows[index].Cells[2].Value=option.Key;grid.Rows[index].Cells[0].Value=true;}await Install();}
  async Task ArchiveCheckedVersions(){if(busy)return;var selected=CheckedOptions();var allowed=selected.Where(o=>PackageVersions.CanRemove(o.Package,store)).GroupBy(o=>PackageVersions.ImportRoot(o.Package,store),StringComparer.OrdinalIgnoreCase).Select(g=>g.First()).ToList();int excluded=selected.Count(o=>!PackageVersions.CanRemove(o.Package,store));string plan=string.Format(L.Get("ArchiveReview"),selected.Count,allowed.Count,excluded)+Environment.NewLine+string.Join(Environment.NewLine,allowed.Select(o=>o.Package.Manifest.name+" · "+o.Package.Manifest.version+Environment.NewLine+PackageVersions.ImportRoot(o.Package,store)))+Environment.NewLine+Environment.NewLine+L.Get("ArchiveHint");if(allowed.Count==0){Dialogs.Show(plan,Text);return;}if(Dialogs.Show(plan,Text,MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return;SetBusy(true,true);try{foreach(var option in allowed){string archive=await Task.Run(()=>PackageVersions.RemoveImport(option.Package,store,settings));Append(L.Get("Text104")+archive);string root=PackageVersions.ImportRoot(new Package{Folder=option.Key},store);imported.RemoveAll(p=>PackageVersions.Under(p.Folder,root));}SaveSettings();checkedVersions.Clear();}catch(Exception ex){Error(ex);}finally{SetBusy(false);}await Scan();}
  async Task ForgetCheckedSources(){if(busy)return;var folders=CheckedOptions().Select(o=>o.Key).Distinct(StringComparer.OrdinalIgnoreCase).Where(path=>settings.packageFolders.Any(p=>Data.Same(p,path))).ToList();if(folders.Count==0){Dialogs.Show(L.Get("ForgetUnavailable"),Text);return;}if(Dialogs.Show(L.Get("ForgetHint")+Environment.NewLine+string.Join(Environment.NewLine,folders),Text,MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;foreach(string folder in folders)settings.packageFolders.RemoveAll(p=>Data.Same(p,folder));SaveSettings();await Scan();}
  void BuildCategories(){var settingsPage=tabs.TabPages[3];var panel=(TableLayoutPanel)settingsPage.Controls[0];var section=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true};section.Controls.Add(new Label{Text=L.Get("Categories"),AutoSize=true});categoryList.Size=new Size(280,90);section.Controls.Add(categoryList);var tools=new FlowLayoutPanel{AutoSize=true};tools.Controls.Add(Button(L.Get("AddCategory"),delegate{EditCategory(false);},L.Get("CategoryHint")));tools.Controls.Add(Button(L.Get("RenameCategory"),delegate{EditCategory(true);},L.Get("CategoryHint")));tools.Controls.Add(Button(L.Get("RemoveCategory"),delegate{RemoveCategory();},L.Get("CategoryHint")));section.Controls.Add(tools);panel.Controls.Add(section,0,4);}
  void RefreshCategories(){if(categoryFilter==null)return;string prior=Convert.ToString(categoryFilter.SelectedItem),assign=Convert.ToString(assignCategory.SelectedItem);categoryFilter.Items.Clear();categoryFilter.Items.Add(L.Get("AllCategories"));categoryFilter.Items.AddRange(settings.categories.Cast<object>().ToArray());categoryFilter.SelectedIndex=Math.Max(0,categoryFilter.Items.IndexOf(prior));assignCategory.Items.Clear();assignCategory.Items.AddRange(settings.categories.Cast<object>().ToArray());if(assignCategory.Items.Count>0)assignCategory.SelectedIndex=Math.Max(0,assignCategory.Items.IndexOf(assign));versionCategory.Items.Clear();versionCategory.Items.AddRange(settings.categories.Cast<object>().ToArray());if(versionCategory.Items.Count>0)versionCategory.SelectedIndex=0;categoryList.Items.Clear();categoryList.Items.AddRange(settings.categories.Cast<object>().ToArray());}
  string AskCategory(string initial){using(var dialog=new Form{Text=L.Get("Categories"),Size=new Size(430,180),StartPosition=FormStartPosition.CenterParent,Font=Font,MinimizeBox=false,MaximizeBox=false}){var input=new TextBox{Text=initial??"",Dock=DockStyle.Top,MaxLength=50};var save=new ModernButton{Text=L.Get("Save"),Dock=DockStyle.Bottom,Height=40,DialogResult=DialogResult.OK};dialog.Controls.Add(input);dialog.Controls.Add(save);dialog.AcceptButton=save;Theme(dialog);return dialog.ShowDialog(this)==DialogResult.OK?input.Text.Trim():null;}}
  void EditCategory(bool rename){string old=rename?Convert.ToString(categoryList.SelectedItem):null;if(rename&&old==null)return;string name=AskCategory(old);if(string.IsNullOrWhiteSpace(name)||name==old)return;if(settings.categories.Contains(name)){Dialogs.Show(L.Get("CategoryExists"),Text);return;}if(rename){settings.categories[settings.categories.IndexOf(old)]=name;foreach(var list in settings.modCategories.Values){int i=list.IndexOf(old);if(i>=0)list[i]=name;}}else settings.categories.Add(name);SaveSettings();RefreshCategories();ApplyFilter();}
  void RemoveCategory(){string name=Convert.ToString(categoryList.SelectedItem);if(string.IsNullOrEmpty(name))return;if(Dialogs.Show(L.Get("RemoveCategoryHint")+Environment.NewLine+name,Text,MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;settings.categories.Remove(name);foreach(var list in settings.modCategories.Values)list.Remove(name);SaveSettings();RefreshCategories();ApplyFilter();}
  void AssignCategory(){string category=Convert.ToString(tabs.SelectedIndex==1?versionCategory.SelectedItem:assignCategory.SelectedItem);if(string.IsNullOrEmpty(category)){tabs.SelectedIndex=3;return;}var ids=(tabs.SelectedIndex==1?CheckedOptions().Select(o=>o.Package.Manifest.id):Selected().Select(RowId)).Distinct().ToList();if(ids.Count==0){Dialogs.Show(L.Get("Text114"),Text);return;}foreach(string id in ids){List<string> list;if(!settings.modCategories.TryGetValue(id,out list)){list=new List<string>();settings.modCategories[id]=list;}if(!list.Contains(category))list.Add(category);}SaveSettings();ApplyFilter();}
  void BuildActivity(){var page=tabs.TabPages[2];page.Controls.Clear();var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=48,Padding=new Padding(4)};activitySearch.Width=260;activitySearch.Margin=new Padding(4,8,8,4);activityKind.DropDownStyle=ComboBoxStyle.DropDownList;activityKind.Width=180;activityKind.Margin=activitySearch.Margin;top.Controls.Add(activitySearch);top.Controls.Add(activityKind);top.Controls.Add(Button(L.Get("CopyActivity"),delegate{CopyText(string.Join(Environment.NewLine,FilteredActivity().Select(e=>e.Time.ToString("HH:mm:ss")+" "+L.Get(e.Kind)+" "+e.Message)));},L.Get("CopyDetails")));activityGrid.VirtualMode=true;activityGrid.CellValueNeeded+=ActivityValue;activityGrid.CellFormatting+=ActivityFormatting;activityGrid.Dock=DockStyle.Fill;activityGrid.AllowUserToAddRows=false;activityGrid.AllowUserToDeleteRows=false;activityGrid.ReadOnly=true;activityGrid.RowHeadersVisible=false;activityGrid.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;activityGrid.Columns.Add("time",L.Get("Time"));activityGrid.Columns.Add("kind",L.Get("Severity"));activityGrid.Columns.Add("operation",L.Get("Operation"));activityGrid.Columns.Add("module",L.Get("Text028"));activityGrid.Columns.Add("message",L.Get("Details"));activityGrid.Columns[4].FillWeight=450;activityGrid.DefaultCellStyle.WrapMode=DataGridViewTriState.True;activityGrid.AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.DisplayedCells;activityGrid.ColumnHeadersHeight=36;page.Controls.Add(activityGrid);page.Controls.Add(top);activitySearch.TextChanged+=delegate{RefreshActivity();};activityKind.SelectedIndexChanged+=delegate{RefreshActivity();};SetActivityKinds();}
  void SetActivityKinds(){int selected=activityKind.SelectedIndex;activityKind.Items.Clear();activityKind.Items.AddRange(new object[]{L.Get("AllActivity"),L.Get("Info"),L.Get("Success"),L.Get("WarningLog"),L.Get("ErrorLog")});activityKind.SelectedIndex=selected<0?0:selected;}
  IEnumerable<ActivityEntry> FilteredActivity(){string[] kinds={null,"Info","Success","WarningLog","ErrorLog"};string kind=activityKind.SelectedIndex>0?kinds[activityKind.SelectedIndex]:null;return activityEntries.Where(e=>(kind==null||kind==e.Kind)&&e.Message.IndexOf(activitySearch.Text.Trim(),StringComparison.CurrentCultureIgnoreCase)>=0);}
  void AddActivity(string message,string explicitKind=null,string module=null,string operation=null){string kind=explicitKind??(message.StartsWith(L.Get("Text131"))||message.StartsWith(L.Get("Text132"))||message.StartsWith(L.Get("Text130"))?"ErrorLog":message.StartsWith(L.Get("Text084"))?"WarningLog":message==L.Get("Text129")||(message.EndsWith(L.Get("Text179"))||message.EndsWith(L.Get("Text183")))||message.StartsWith(L.Get("Text055"))?"Success":"Info");var current=rows.FirstOrDefault(r=>!string.IsNullOrEmpty(r.Operation));activityEntries.Add(new ActivityEntry{Time=DateTime.Now,Kind=kind,Operation=operation??(current==null?L.Get("Text064"):current.Operation),Module=module??(current==null?"":current.Package==null?current.Installed.name:current.Package.Manifest.name),Message=message});if(activityEntries.Count>3000)activityEntries.RemoveRange(0,activityEntries.Count-3000);if(activityGrid.Columns.Count>0&&tabs.SelectedIndex==2)RefreshActivity();}
  List<ActivityEntry> visibleActivity=new List<ActivityEntry>();
  void ActivityValue(object sender,DataGridViewCellValueEventArgs e){if(e.RowIndex<0||e.RowIndex>=visibleActivity.Count)return;var item=visibleActivity[e.RowIndex];e.Value=e.ColumnIndex==0?item.Time.ToString("HH:mm:ss"):e.ColumnIndex==1?L.Get(item.Kind):e.ColumnIndex==2?item.Operation:e.ColumnIndex==3?item.Module:item.Message;}
  void ActivityFormatting(object sender,DataGridViewCellFormattingEventArgs e){if(e.RowIndex<0||e.RowIndex>=visibleActivity.Count||e.ColumnIndex!=1)return;string kind=visibleActivity[e.RowIndex].Kind;e.CellStyle.ForeColor=kind=="ErrorLog"?Color.FromArgb(220,38,38):kind=="WarningLog"?Color.FromArgb(180,83,9):kind=="Success"?Color.FromArgb(22,130,74):Color.FromArgb(71,85,105);}
  void RefreshActivity(){if(activityGrid.Columns.Count==0)return;activityGrid.CurrentCell=null;activityGrid.ClearSelection();activityGrid.AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.None;visibleActivity=FilteredActivity().ToList();activityGrid.RowCount=visibleActivity.Count;activityGrid.AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.DisplayedCells;activityGrid.Invalidate();}
